"""Auto-generated experiment report (Rule 9: numbers are never hand-written).

`docs/chunking-experiments.md` is produced by this writer from measured
StrategyResults. The committed copy is a scaffold; running the script fills
it with real values.
"""

from __future__ import annotations

from collections.abc import Sequence
from datetime import datetime, timezone
from pathlib import Path

from app.evaluation.chunking_eval.corpus import CORPUS_VERSION
from app.evaluation.chunking_eval.runner import StrategyResult
from app.evaluation.chunking_eval.samples import SAMPLES_VERSION

_DECISION_RULE = (
    "Per ADR-003, the default strategy is replaced only if another strategy wins "
    "on both Recall@10 and MRR without regressing Precision@5 by more than 5 points."
)


def render_report(
    results: Sequence[StrategyResult],
    *,
    corpus_size: int,
    n_samples: int,
    retrieval_depth: int,
    k_values: Sequence[int],
) -> str:
    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    lines: list[str] = []
    lines.append("# Chunking Experiments (Phase 5)")
    lines.append("")
    lines.append(f"> Auto-generated by `scripts/run_chunking_experiments.py` on {now}.")
    lines.append(f"> Corpus: `{CORPUS_VERSION}` ({corpus_size} documents) · Samples: `{SAMPLES_VERSION}` ({n_samples} questions) · Retrieval depth: {retrieval_depth}")
    lines.append("")
    lines.append("## Methodology")
    lines.append("")
    lines.append("- **Retriever held constant:** in-memory Okapi BM25 (lexical). Dense retrieval does not exist yet (Phase 6+), so this phase isolates the chunking variable under lexical search only.")
    lines.append("- **Ground truth:** evidence-based. Each question carries verbatim evidence spans; a chunk is gold iff it contains a span (normalized) or reaches ≥0.7 token-overlap. Gold sets are recomputed per strategy — the comparison stays fair because chunks differ across strategies.")
    lines.append("- **Pipeline fidelity:** corpus runs through the real ingestion path (MarkdownParser → cleaner → structure annotator → chunker). No experiment-only code paths.")
    lines.append("- **Not measured yet (deferred honestly):** context relevance and answer correctness require embeddings + LLM (Phases 21–22).")
    lines.append("")
    lines.append("## Results")
    lines.append("")
    header = ["Strategy", "MRR"] + [f"Recall@{k}" for k in k_values] + [f"Precision@{k}" for k in k_values] + [f"Hit@{k}" for k in k_values]
    lines.append("| " + " | ".join(header) + " |")
    lines.append("|" + "---|" * len(header))
    for r in results:
        row = [r.strategy, f"{r.metrics.get('mrr', 0):.4f}"]
        row += [f"{r.metrics.get(f'recall_at_{k}', 0):.4f}" for k in k_values]
        row += [f"{r.metrics.get(f'precision_at_{k}', 0):.4f}" for k in k_values]
        row += [f"{r.metrics.get(f'hit_rate_at_{k}', 0):.4f}" for k in k_values]
        lines.append("| " + " | ".join(row) + " |")
    lines.append("")
    lines.append("## Chunk set characteristics")
    lines.append("")
    lines.append("| Strategy | Chunks | Mean tokens | Median tokens | Max tokens | % below min |")
    lines.append("|---|---|---|---|---|---|")
    for r in results:
        s = r.stats
        lines.append(
            f"| {r.strategy} | {s.n_chunks} | {s.mean_tokens} | {s.median_tokens} | {s.max_tokens} | {s.pct_below_min_tokens} |"
        )
    lines.append("")
    lines.append("## Interpretation")
    lines.append("")
    if results:
        best_recall = max(results, key=lambda r: r.metrics.get("recall_at_10", 0))
        best_mrr = max(results, key=lambda r: r.metrics.get("mrr", 0))
        lines.append(f"- Best Recall@10: **{best_recall.strategy}** ({best_recall.metrics.get('recall_at_10', 0):.4f})")
        lines.append(f"- Best MRR: **{best_mrr.strategy}** ({best_mrr.metrics.get('mrr', 0):.4f})")
    lines.append(f"- {_DECISION_RULE}")
    lines.append("")
    lines.append("## Caveats")
    lines.append("")
    lines.append("- Lexical-only retrieval: dense/hybrid comparisons land with Phases 6–8 and may change the ranking.")
    lines.append("- Synthetic corpus (4 documents, 30 questions): directional evidence, not a production-scale claim.")
    lines.append("- Token counts use the heuristic counter (≈4 chars/token); Phase 6 introduces model-aware counting.")
    lines.append("")
    return "\n".join(lines)


def write_report(
    results: Sequence[StrategyResult],
    *,
    output_path: Path,
    corpus_size: int,
    n_samples: int,
    retrieval_depth: int,
    k_values: Sequence[int],
) -> Path:
    content = render_report(
        results,
        corpus_size=corpus_size,
        n_samples=n_samples,
        retrieval_depth=retrieval_depth,
        k_values=k_values,
    )
    output_path.write_text(content, encoding="utf-8")
    return output_path